<?php
declare(strict_types=1);
final class CharacterController{
private const VOCATIONS=['knight'=>'Cavaleiro','sorcerer'=>'Feiticeiro','druid'=>'Druida','ranger'=>'Patrulheiro'];
public static function index():void{$u=require_auth();$q=db()->prepare('SELECT c.id,c.name,c.level,v.name vocation FROM characters c JOIN vocations v ON v.code=c.vocation_code WHERE c.user_id=? ORDER BY c.created_at');$q->execute([$u['id']]);$rows=$q->fetchAll();$f=consume_flash();ob_start();?><section class="wrap"><small>SUA CONTA</small><h1>Seus personagens</h1><p class="muted">Escolha um aventureiro ou comece uma nova história.</p><?php if($f):?><div class="notice"><?=e($f['message'])?></div><?php endif;?><div class="cards"><?php foreach($rows as $c):?><article class="card"><b>✧</b><h2><?=e($c['name'])?></h2><p><?=e($c['vocation'])?> · Nível <?=(int)$c['level']?></p><a class="button primary" href="/game?character=<?=(int)$c['id']?>">Entrar no mundo</a></article><?php endforeach;?><article class="card"><b>＋</b><h2>Novo aventureiro</h2><a class="button secondary" href="/characters/create">Criar personagem</a></article></div></section><?php render('Personagens',(string)ob_get_clean());}
public static function create():void{$u=require_auth();if($_SERVER['REQUEST_METHOD']==='GET'){ob_start();?><section class="auth"><div class="panel"><small>FORJE SEU DESTINO</small><h1>Criar personagem</h1><?php $f=consume_flash();if($f):?><div class="notice"><?=e($f['message'])?></div><?php endif;?><form method="post" class="stack"><?=csrf_field()?><label>Nome<input name="name" minlength="3" maxlength="20" required></label><label>Vocação<select name="vocation"><?php foreach(self::VOCATIONS as $code=>$name):?><option value="<?=e($code)?>"><?=e($name)?></option><?php endforeach;?></select></label><button class="button primary">Criar personagem</button></form></div></section><?php render('Criar personagem',(string)ob_get_clean());return;}verify_csrf();$name=trim((string)($_POST['name']??''));$voc=(string)($_POST['vocation']??'');if(!preg_match('/^[\p{L}0-9 ]{3,20}$/u',$name)||!isset(self::VOCATIONS[$voc])){flash('Nome ou vocação inválidos.','error');redirect('/characters/create');}$q=db()->prepare('SELECT COUNT(*) FROM characters WHERE user_id=?');$q->execute([$u['id']]);if((int)$q->fetchColumn()>=3){flash('Limite de 3 personagens por conta.','error');redirect('/characters');}try{$q=db()->prepare('INSERT INTO characters(user_id,name,vocation_code,level,experience,health,mana,map_code,tile_x,tile_y,created_at,updated_at) SELECT ?,?,?,1,0,base_health,base_mana,\'elarion\',8,8,UTC_TIMESTAMP(),UTC_TIMESTAMP() FROM vocations WHERE code=?');$q->execute([$u['id'],$name,$voc,$voc]);flash('Personagem criado.','success');redirect('/characters');}catch(PDOException $e){flash('Nome indisponível. Tente outro.','error');redirect('/characters/create');}}
public static function game():void{$u=require_auth();$id=filter_input(INPUT_GET,'character',FILTER_VALIDATE_INT);$q=db()->prepare('SELECT c.*,v.name vocation,v.base_health max_health,v.base_mana max_mana FROM characters c JOIN vocations v ON v.code=c.vocation_code WHERE c.id=? AND c.user_id=? LIMIT 1');$q->execute([(int)$id,$u['id']]);$c=$q->fetch();if(!$c)redirect('/characters');$en=db()->prepare('SELECT id,code,name,tile_x,tile_y,health,max_health,level FROM world_creatures WHERE map_code=? AND health>0');$en->execute([$c['map_code']]);$creatures=$en->fetchAll();ob_start();?><section class="wrap"><div class="game-head"><div><small>CONTINENTE DE ELARION</small><h1><?=e($c['name'])?></h1><p><?=e($c['vocation'])?> · Nível <?=(int)$c['level']?></p></div><a href="/characters">Trocar personagem</a></div><div class="stage"><canvas id="world" width="960" height="600" aria-label="Mapa isométrico de Elarion"></canvas><div class="overlay">MOVIMENTO: WASD OU SETAS · POSIÇÃO SALVA AUTOMATICAMENTE</div></div><div class="game-controls" aria-label="Controles de movimento"><button type="button" data-move="0,-1" aria-label="Mover para cima">▲</button><div><button type="button" data-move="-1,0" aria-label="Mover para esquerda">◀</button><button type="button" data-move="0,1" aria-label="Mover para baixo">▼</button><button type="button" data-move="1,0" aria-label="Mover para direita">▶</button></div></div><p id="save-status" class="save-status" role="status">Conectado ao mundo</p><div class="encounters"><h2>Habitantes hostis</h2><p class="muted">Aproxime-se de uma criatura e ataque para ganhar experiência.</p><div id="creature-list" class="creature-list"><?php foreach($creatures as $enemy):?><button type="button" class="creature-button" data-creature="<?=(int)$enemy['id']?>">⚔ <?=e($enemy['name'])?> · Nv. <?=(int)$enemy['level']?> · Vida <?=(int)$enemy['health']?>/<?=(int)$enemy['max_health']?></button><?php endforeach;?></div><p id="combat-status" class="save-status" role="status">Nenhum combate iniciado</p></div><div class="stats"><div>VIDA<strong><?=(int)$c['health']?> / <?=(int)$c['max_health']?></strong></div><div>MANA<strong><?=(int)$c['mana']?> / <?=(int)$c['max_mana']?></strong></div><div>EXPERIÊNCIA<strong id="experience-value"><?=(int)$c['experience']?> XP</strong></div></div><p class="muted">Você pode caminhar pelo vale. O progresso de posição é salvo na sua conta.</p></section><script>window.AETHORIA_WORLD=<?=json_encode(['x'=>(int)$c['tile_x'],'y'=>(int)$c['tile_y'],'character'=>(int)$c['id'],'csrf'=>csrf_token(),'name'=>$c['name'],'creatures'=>$creatures],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;</script><script src="/assets/js/game.js" defer></script><?php render('Mundo',(string)ob_get_clean());}
public static function move():void{$u=require_auth();header('Content-Type: application/json; charset=utf-8');if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST'){http_response_code(405);echo json_encode(['ok'=>false,'message'=>'Método não permitido']);return;}if(!self::validToken()){http_response_code(419);echo json_encode(['ok'=>false,'message'=>'Sessão expirada']);return;}$data=json_decode((string)file_get_contents('php://input'),true)?:[];$id=filter_var($data['character']??null,FILTER_VALIDATE_INT);$x=filter_var($data['x']??null,FILTER_VALIDATE_INT);$y=filter_var($data['y']??null,FILTER_VALIDATE_INT);if(!$id||$x===false||$y===false||$x<0||$x>=18||$y<0||$y>=15){http_response_code(422);echo json_encode(['ok'=>false,'message'=>'Posição inválida']);return;}$q=db()->prepare('SELECT tile_x,tile_y FROM characters WHERE id=? AND user_id=?');$q->execute([$id,$u['id']]);$current=$q->fetch();if(!$current){http_response_code(404);echo json_encode(['ok'=>false,'message'=>'Personagem não encontrado']);return;}if(abs($x-(int)$current['tile_x'])+abs($y-(int)$current['tile_y'])!==1||self::blocked($x,$y)){http_response_code(422);echo json_encode(['ok'=>false,'message'=>'Movimento bloqueado']);return;}$q=db()->prepare('SELECT id FROM world_creatures WHERE map_code=\'elarion\' AND health>0 AND tile_x=? AND tile_y=?');$q->execute([$x,$y]);if($q->fetch()){http_response_code(409);echo json_encode(['ok'=>false,'message'=>'Uma criatura ocupa esse espaço']);return;}$q=db()->prepare('UPDATE characters SET tile_x=?,tile_y=?,updated_at=UTC_TIMESTAMP() WHERE id=? AND user_id=?');$q->execute([$x,$y,$id,$u['id']]);echo json_encode(['ok'=>true,'x'=>$x,'y'=>$y]);}
public static function attack():void{$u=require_auth();header('Content-Type: application/json; charset=utf-8');if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST'){http_response_code(405);echo json_encode(['ok'=>false,'message'=>'Método não permitido']);return;}if(!self::validToken()){http_response_code(419);echo json_encode(['ok'=>false,'message'=>'Sessão expirada']);return;}$data=json_decode((string)file_get_contents('php://input'),true)?:[];$id=filter_var($data['character']??null,FILTER_VALIDATE_INT);$enemyId=filter_var($data['creature']??null,FILTER_VALIDATE_INT);if(!$id||!$enemyId){http_response_code(422);echo json_encode(['ok'=>false,'message'=>'Alvo inválido']);return;}$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT id,tile_x,tile_y,vocation_code,level FROM characters WHERE id=? AND user_id=? FOR UPDATE');$q->execute([$id,$u['id']]);$c=$q->fetch();if(!$c){$pdo->rollBack();http_response_code(404);echo json_encode(['ok'=>false,'message'=>'Personagem não encontrado']);return;}$q=$pdo->prepare('SELECT * FROM world_creatures WHERE id=? AND map_code=\'elarion\' FOR UPDATE');$q->execute([$enemyId]);$e=$q->fetch();if(!$e|| (int)$e['health']<=0){$pdo->rollBack();http_response_code(404);echo json_encode(['ok'=>false,'message'=>'Criatura não encontrada ou derrotada']);return;}if(abs((int)$c['tile_x']-(int)$e['tile_x'])+abs((int)$c['tile_y']-(int)$e['tile_y'])>1){$pdo->rollBack();http_response_code(422);echo json_encode(['ok'=>false,'message'=>'Chegue mais perto para atacar']);return;}$damage=['knight'=>24,'sorcerer'=>30,'druid'=>20,'ranger'=>26][$c['vocation_code']] + min(20,(int)$c['level']*2);$remaining=max(0,(int)$e['health']-$damage);$q=$pdo->prepare('UPDATE world_creatures SET health=? WHERE id=?');$q->execute([$remaining,$enemyId]);$xp=0;if($remaining===0){$xp=(int)$e['experience_reward'];$q=$pdo->prepare('UPDATE characters SET experience=experience+?,updated_at=UTC_TIMESTAMP() WHERE id=?');$q->execute([$xp,$id]);}$pdo->commit();echo json_encode(['ok'=>true,'damage'=>$damage,'remaining'=>$remaining,'defeated'=>$remaining===0,'experience'=>$xp,'creature'=>$e['name']]);}catch(Throwable $err){if($pdo->inTransaction())$pdo->rollBack();throw $err;}}
private static function validToken():bool{$token=$_SERVER['HTTP_X_CSRF_TOKEN']??'';return is_string($token)&&hash_equals(csrf_token(),$token);}
private static function blocked(int $x,int $y):bool{$n=($x*17+$y*29+$x*$y*3)%31;$blocked=in_array($n,[2,9,21,14],true);if(in_array($x.','.$y,['8,8','8,7','7,8','9,8','8,9','4,4','13,10','3,11'],true))$blocked=false;return $blocked;}
}